/** Polls up to 50 times waiting for a condition to become true, sleeping 10ms between polls. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Returns arrays that tests push connection and disconnection events into. */
export function trackConnections(): {servers: ReturnType<typeof createServer>[]; clients: WebSocket[]} {
  return {servers: [], clients: []};
}

